DESIGN='1080×1350 portrait; beige #FBE7C5; deep green #144D3C; Lora headings, Canva Sans body subject to license confirmation; white/black restrained; owned logo only when verified. Keep generous margins, large text, 1 idea/slide. No stock client proof or face. All visuals are design instructions, NOT rendered media.'

def draft(i, d):
    hook, situation, example, first, second, result = ROWS[i][d]
    if i==0: slides=[hook,situation,f'Look for this friction: {example}',f'First repair: {first}',f'Then: {second}',f'Check: {result}. Save this diagnosis.']
    elif i==1: slides=[hook,situation,f'Concrete example: {example}',first,second,f'Use this check: {result}. Save for planning.']
    elif i==2: slides=[hook,situation,f'Example, not evidence: {example}',first,second,f'What to watch: {result}. Share with context.']
    elif i==3: slides=[hook,situation,f'The frustration: {example}',f'One move you control: {first}',second,f'{result}. Send this to an owner who gets it.']
    elif i==4: slides=[hook,'Hypothetical starting point: '+situation,'Investigate first: '+example,'Priority: '+first,'Change: '+second,'Implementation: '+IMPLEMENTATIONS[d],'Measure: '+result,'Aim: clearer, better-qualified next steps; no result is promised. Save this plan.']
    elif i==5: slides=[hook,situation,'Documented basis: '+example,'Next step: '+first,'Then: '+second,f'{result}. Ask what applies to your project.']
    elif i==6: slides=[hook,situation,'Why it fails: '+example,'Illustrative rewrite: '+first,'Add this: '+second,f'{result}. Save the before/after.']
    elif i==7: slides=[hook,situation,'Underlying principle: '+example,'What to do: '+first,'Original application: '+second.removeprefix('Original example: '),f'{result}. Save the move.']
    elif i==8: slides=[hook,situation,'Input / safe job: '+example,'Human control: '+first,'Boundary: '+second,f'Pilot check: {result}. Save this workflow.']
    elif i==9: slides=[hook,'Who may need it: '+situation,'Documented category: '+example,'Possible deliverable: '+first,'Confirm before purchase: '+second,f'How to enquire: {result}']
    else: slides=[hook,situation,example,first,second,f'{result}. Follow Easywurld for practical growth thinking.']
    return slides

# Selected placement hypothesis from the newer living prompt. Never promoted to Scheduled.
def assignment(day_index):
    rotate=day_index%11
    selected=[CHANNELS[(n+rotate)%11] for n in range(11)]
    counters={p:0 for p in BASE_TIMES}
    out=[]
    for channel in selected:
        out.append((channel,BASE_TIMES[channel][counters[channel]])); counters[channel]+=1
    return out

