from difflib import SequenceMatcher
legacy=json.loads((ROOT.parent/'content-plan.json').read_text())['posts']
legacy=[r for r in legacy if r.get('type')=='Content']
def similarity(a,b):
    return SequenceMatcher(None,a.lower(),b.lower()).ratio()
with (ROOT/'05_DUPLICATION_TRACKER.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.writer(f);w.writerow(['new_id','new_hook','legacy_day','closest_existing_id','closest_existing_topic','hook_similarity_0_to_1','closest_any_month_id','closest_any_month_topic','any_month_similarity','risk','action'])
    for p in posts:
        day=int(p['date'][-2:])-1
        candidates=[r for r in legacy if r['date']==p['date']]
        nearest=max(candidates,key=lambda r: similarity(p['hook'],r.get('hook','')))
        score=similarity(p['hook'],nearest.get('hook',''))
        any_month=max(legacy,key=lambda r: similarity(p['hook'],r.get('hook','')))
        any_score=similarity(p['hook'],any_month.get('hook',''))
        w.writerow([p['id'],p['hook'],f'Day_{day:02d}',nearest['id'],nearest['topic'],f'{score:.2f}',any_month['id'],any_month['topic'],f'{any_score:.2f}','high: same-date eleven-slot collision; similarity is a screening hint, not clearance','compare topic, angle, example, pending queues and old assets manually; choose one plan before scheduling'])

